S = "Hakeem Force Academy"
QS = [
(S, "What is the main duty of Hazrat Jibrael (AS)?", ["To bring revelation (wahi) from Allah to the Prophets", "To blow the Trumpet on the Day of Judgement", "To distribute rain and sustenance", "To take the souls of the dying"], 0, "Hazrat Jibrael (AS) is the angel who carried Allah's revelation to the Prophets, including the Quran to Prophet Muhammad (PBUH).", "Hazrat Israfil (AS) will blow the Trumpet, Hazrat Mikael (AS) is in charge of rain and Hazrat Izrael (AS) takes souls.", [3064]),
(S, "What is the measure of each angle of a square?", ["60 degrees", "90 degrees", "120 degrees", "180 degrees"], 1, "A square has four equal angles and the angles of a quadrilateral add up to 360 degrees, so each is 360 / 4 = 90 degrees.", "The diagonals of a square are equal and bisect each other at right angles.", [3045]),
(S, "What large sea wave is usually caused by an earthquake under the ocean floor?", ["Tide", "Tsunami", "Whirlpool", "Current"], 1, "A strong undersea earthquake suddenly moves the sea floor and displaces a huge volume of water, which travels as a tsunami.", "The 2004 Indian Ocean tsunami was caused by a magnitude 9 earthquake near Sumatra.", [854]),
(S, "Which instrument is used to record and measure earthquakes?", ["Barometer", "Seismograph", "Anemometer", "Hygrometer"], 1, "A seismograph records the vibrations of seismic waves produced by an earthquake.", "The Richter scale is the scale commonly used to express the magnitude of an earthquake.", [5263]),
(S, "In the sentence \"How many burgers had you eaten yesterday?\", which part of speech is \"how many\"?", ["Noun", "Pronoun", "Interjection", "Adjective"], 3, "\"How many\" asks about quantity and describes the noun \"burgers\", so it works as an (interrogative) adjective.", "Adjectives of quantity answer the questions how much or how many.", [4594]),
(S, "How many vowels are there in the string EAVNJEGFDUI?", ["4", "6", "5", "3"], 2, "The letters are E, A, V, N, J, E, G, F, D, U, I. The vowels are E, A, E, U and I, which makes 5.", "The English vowels are A, E, I, O and U.", [1938, 708, 1939]),
(S, "In which year did Pakistan become a founding member of the Economic Cooperation Organization (ECO) in its present form?", ["1985", "1964", "1992", "1979"], 0, "The Economic Cooperation Organization was revived in 1985 by Pakistan, Iran and Turkey, so Pakistan has been a member since then.", "ECO replaced the Regional Cooperation for Development (RCD) of 1964 and was expanded in 1992 to include Central Asian states.", [4014]),
(S, "Pakistan's economy has traditionally been described as predominantly what kind of economy?", ["Industrial", "Agricultural", "Mining based", "Oil based"], 1, "Pakistani textbooks describe the country as agricultural because agriculture supports most of the rural population and provides raw material to industry.", "Today the services sector gives the largest share of GDP, while agriculture still employs about a third or more of the workforce.", [2911, 4141]),
(S, "Which word is closest in meaning to \"efficient\"?", ["Wasteful", "Capable", "Slow", "Careless"], 1, "Efficient means able to do something well with little waste of time or effort, which matches capable or competent.", "The noun form is efficiency and its opposite is inefficiency.", [3260]),
(S, "B is 6 years older than A. At what age of A will B be 3 times as old as A?", ["3 years", "6 years", "2 years", "9 years"], 0, "Let A be x. Then B is x + 6 and x + 6 = 3x, so 2x = 6 and x = 3.", "At that time B is 9 years old, exactly 3 times A's age of 3.", [1333]),
(S, "Usman is older than Khalid, and Khalid is older than Kadir. Who is the eldest?", ["Khalid", "Kadir", "Usman", "Cannot be determined"], 2, "Usman is older than Khalid and Khalid is older than Kadir, so the order is Usman, Khalid, Kadir.", "Such ordering problems are solved by writing the persons in a line from oldest to youngest.", [2091]),
(S, "By whom is the Prime Minister of Pakistan elected under the 1973 Constitution?", ["The President directly", "The National Assembly", "The Senate", "The Supreme Court"], 1, "The Prime Minister is elected by the members of the National Assembly, usually the leader who has a majority there.", "The President then appoints the elected member as Prime Minister.", [640]),
(S, "Who was the first woman elected to the United States Congress?", ["Jeannette Rankin", "Hillary Clinton", "Eleanor Roosevelt", "Nancy Pelosi"], 0, "Jeannette Rankin of Montana was elected to the US House of Representatives in 1916 and took her seat in 1917.", "Nancy Pelosi became the first woman Speaker of the US House in 2007.", [5102]),
(S, "In which year was the second general election held in Pakistan?", ["1977", "1985", "1988", "1962"], 0, "Pakistan's first general election on adult franchise was held in 1970 and the second in March 1977.", "The 1977 election led to protests and the martial law of General Zia ul Haq in July 1977.", [2389]),
(S, "In which year was the first general election held in Pakistan on the basis of adult franchise?", ["1970", "1962", "1956", "1977"], 0, "The first direct general election on adult franchise took place in December 1970 under General Yahya Khan.", "The Awami League won a majority in the National Assembly in this election.", [2397]),
(S, "In which year did the Muslims of the subcontinent get the right of separate electorates?", ["1906", "1909", "1919", "1935"], 1, "Separate electorates were granted to the Muslims by the Morley-Minto Reforms of 1909.", "The Lucknow Pact of 1916 later made the Congress accept separate electorates.", [2336, 1082, 478]),
(S, "What did the Fourteen Points of Quaid-e-Azam (1929) demand about electorates?", ["Joint electorates for all", "Separate electorates to continue for Muslims", "No elections at all", "Electorates based on property only"], 1, "The Fourteen Points demanded that Muslims keep their separate electorates until they themselves agreed to give them up.", "The Fourteen Points were presented in March 1929 as an answer to the Nehru Report.", [3977]),
(S, "If sets A and B have no common element, what is n(A union B)?", ["n(A) - n(B)", "n(A) x n(B)", "n(A) + n(B)", "Zero"], 2, "For any sets n(A union B) = n(A) + n(B) - n(A intersection B). With no common element the intersection is empty, so n(A union B) = n(A) + n(B).", "Sets with no common element are called disjoint sets.", [2043]),
(S, "What is the antonym of \"embrace\" in the sense of accepting an idea?", ["Welcome", "Reject", "Adopt", "Hug"], 1, "To embrace an idea is to accept it eagerly, so its opposite is to reject it.", "Embrace also means to hold someone in the arms, and in that sense a synonym is hug.", [3143, 466, 3713]),
(S, "Where does the Indus River rise and where does it fall?", ["Rises near Lake Mansarovar in Tibet and falls into the Arabian Sea", "Rises in the Hindu Kush and falls into the Bay of Bengal", "Rises in the Karakoram and falls into the Persian Gulf", "Rises in Kashmir and falls into the Arabian Sea at Gwadar"], 0, "The Indus rises from the Tibetan plateau near Lake Mansarovar, flows through Ladakh and Pakistan and ends in the Arabian Sea near Karachi.", "It is Pakistan's longest river.", [4143]),
(S, "Where is the headquarters of the International Atomic Energy Agency (IAEA)?", ["Geneva", "New York", "Vienna", "Paris"], 2, "The IAEA is based in Vienna, Austria, and works for peaceful use of nuclear energy.", "The IAEA was founded in 1957 and is linked to the United Nations system.", [4222]),
(S, "What is the antonym of \"entirely\"?", ["Completely", "Partially", "Totally", "Wholly"], 1, "Entirely means completely, and its opposite is partially, which means only in part.", "Other opposites are partly and slightly.", [3144]),
(S, "What is the equation y = 7x + 7 called?", ["Quadratic equation", "Cubic equation", "Linear equation", "Exponential equation"], 2, "The highest power of the variables x and y is 1, so it is a linear equation.", "The graph of a linear equation in two variables is a straight line.", [2098]),
(S, "The algebraic expression 4a - 5b - 6 is what kind of expression?", ["Linear", "Quadratic", "Cubic", "Constant"], 0, "Each variable has power 1, so the degree of the expression is 1 and it is a linear expression.", "The expression 8y - 6x + 7 is also linear.", [3377, 4371]),
(S, "Which word is closest in meaning to \"essential\"?", ["Optional", "Necessary", "Minor", "Extra"], 1, "Essential means absolutely needed, which is the meaning of necessary.", "Other synonyms are vital and indispensable.", [1610, 1023]),
]
